import React from 'react';
import { Routes, Route } from 'react-router-dom';
import DriverNotification  from '../components/DriverNotification';
import DeliveryDashboard   from '../components/DeliveryDashboard';
import CreateDeliveryForm  from '../components/CreateDeliveryForm';
import EditDeliveryForm    from '../components/EditDeliveryForm';
import DriverList          from '../components/DriverList';
import EditDriverForm      from '../components/EditDriverForm';
import AnalyticsDashboard  from '../components/AnalyticsDashboard';
import CustomerTrackPage   from '../pages/CustomerTrackPage';

export default () => (
  <>
    <DriverNotification />
    <Routes>
      <Route path="/track/:id"         element={<CustomerTrackPage />} />
      <Route path="/"                  element={<DeliveryDashboard />} />
      <Route path="/create"            element={<CreateDeliveryForm />} />
      <Route path="/edit-delivery/:id" element={<EditDeliveryForm />} />
      <Route path="/drivers"           element={<DriverList />} />
      <Route path="/edit-driver/:id"   element={<EditDriverForm />} />
      <Route path="/analytics"         element={<AnalyticsDashboard />} />
      <Route path="*"                  element={<div>404 Not Found</div>} />
    </Routes>
  </>
);
